<?php
declare(strict_types=1);
require dirname(__DIR__,2) . '/app/bootstrap.php';
require_admin();
$modules = [
 'services'=>['table'=>'services','title'=>'Care services','fields'=>['title'=>['Title','text'],'slug'=>['URL slug','text'],'summary'=>['Description','textarea'],'icon'=>['Icon','text'],'sort_order'=>['Sort order','number'],'active'=>['Published','checkbox']]],
 'locations'=>['table'=>'locations','title'=>'Office locations','fields'=>['state'=>['State','text'],'city'=>['City','text'],'address'=>['Street address','text'],'zip_code'=>['ZIP code','text'],'phone'=>['Phone','text'],'hours'=>['Hours','text'],'active'=>['Published','checkbox']]],
 'resources'=>['table'=>'resources','title'=>'Family resources','fields'=>['category'=>['Category','text'],'title'=>['Title','text'],'summary'=>['Summary','textarea'],'read_time'=>['Read time','text'],'icon'=>['Icon','text'],'published'=>['Published','checkbox']]],
 'faqs'=>['table'=>'faqs','title'=>'Frequently asked questions','fields'=>['question'=>['Question','text'],'answer'=>['Answer','textarea'],'sort_order'=>['Sort order','number'],'active'=>['Published','checkbox']]],
 'testimonials'=>['table'=>'testimonials','title'=>'Family testimonials','fields'=>['customer_name'=>['Name','text'],'location'=>['Location','text'],'quote'=>['Testimonial','textarea'],'rating'=>['Rating (1–5)','number'],'active'=>['Published','checkbox']]],
 'caregivers'=>['table'=>'caregivers','title'=>'Caregiver profiles','fields'=>['full_name'=>['Full name','text'],'role'=>['Role','text'],'experience'=>['Experience','text'],'specialties'=>['Specialties (comma separated)','text'],'photo_url'=>['Photo URL (optional)','text'],'active'=>['Published','checkbox']]],
];
$page = (string)($_GET['page'] ?? 'dashboard');
if (!in_array($page, ['dashboard','inquiries','applications','settings', ...array_keys($modules)], true)) $page='dashboard';
$error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf(); $action=(string)($_POST['action']??'');
    try {
      if ($action==='save_content' && isset($modules[$page])) {
        $module=$modules[$page]; $data=[];
        foreach ($module['fields'] as $key=>$meta) {
          if ($meta[1]==='checkbox') $data[$key]=isset($_POST[$key])?1:0;
          elseif ($key==='slug') $data[$key]=slugify(trim((string)($_POST[$key]??'')) ?: (string)($_POST['title']??''));
          else $data[$key]=trim((string)($_POST[$key]??''));
        }
        foreach ($module['fields'] as $key=>$meta) if ($meta[1]!=='checkbox' && $key!=='photo_url' && $data[$key]==='') throw new InvalidArgumentException($meta[0] . ' is required.');
        $id=(int)($_POST['id']??0); $columns=array_keys($data);
        if ($id) { $set=implode(',',array_map(fn($c)=>"`$c`=?",$columns)); $stmt=db()->prepare("UPDATE `{$module['table']}` SET $set WHERE id=?"); $stmt->execute([...array_values($data),$id]); flash('Changes saved.'); }
        else { $cols=implode(',',array_map(fn($c)=>"`$c`",$columns)); $marks=implode(',',array_fill(0,count($columns),'?')); $stmt=db()->prepare("INSERT INTO `{$module['table']}` ($cols) VALUES ($marks)"); $stmt->execute(array_values($data)); flash('Item added.'); }
      } elseif ($action==='delete_content' && isset($modules[$page])) {
        $stmt=db()->prepare("DELETE FROM `{$modules[$page]['table']}` WHERE id=?"); $stmt->execute([(int)($_POST['id']??0)]); flash('Item removed.');
      } elseif ($action==='update_status' && in_array($page,['inquiries','applications'],true)) {
        $allowed=$page==='inquiries'?['new','contacted','closed']:['new','reviewing','contacted','closed']; $status=(string)($_POST['status']??''); if(!in_array($status,$allowed,true)) throw new InvalidArgumentException('Choose a valid status.');
        $table=$page==='inquiries'?'inquiries':'applications'; $stmt=db()->prepare("UPDATE `$table` SET status=? WHERE id=?"); $stmt->execute([$status,(int)($_POST['id']??0)]); flash('Submission status updated.');
      } elseif ($action==='save_settings') {
        $allowed=['phone','phone_link','email','hero_intro']; $stmt=db()->prepare('INSERT INTO settings (setting_key,setting_value) VALUES (?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');
        foreach($allowed as $key) $stmt->execute([$key,trim((string)($_POST[$key]??''))]); flash('Website details saved.');
      }
    } catch(Throwable $ex) { $error=$ex instanceof InvalidArgumentException?$ex->getMessage():'Could not save changes. Check that a unique URL slug is not already in use.'; }
    if (!$error) redirect('/admin/?page=' . urlencode($page) . (isset($_POST['id']) && $action==='save_content' ? '&edit='.(int)$_POST['id'] : ''));
}
$flash=get_flash(); $module=$modules[$page]??null; $editing=null; $rows=[];
if($module){ $rows=db()->query("SELECT * FROM `{$module['table']}` ORDER BY id DESC")->fetchAll(); if(isset($_GET['edit'])) { $st=db()->prepare("SELECT * FROM `{$module['table']}` WHERE id=?");$st->execute([(int)$_GET['edit']]);$editing=$st->fetch()?:null; } }
if(in_array($page,['inquiries','applications'],true)) { $table=$page==='inquiries'?'inquiries':'applications';$rows=db()->query("SELECT * FROM `$table` ORDER BY created_at DESC LIMIT 250")->fetchAll(); }
$titles=['dashboard'=>'Overview','inquiries'=>'Care requests','applications'=>'Job applications','settings'=>'Website details']; if($module)$titles[$page]=$module['title'];
$counts=[]; $dashboardServices=[]; if($page==='dashboard'){foreach(['inquiries'=>'Care requests','applications'=>'Applications','services'=>'Services','locations'=>'Locations'] as $table=>$label){$counts[$label]=(int)db()->query("SELECT COUNT(*) FROM `$table`".($table==='services'||$table==='locations'?' WHERE active=1':' WHERE status=\'new\''))->fetchColumn();} $dashboardServices=db()->query('SELECT title FROM services WHERE active=1 ORDER BY sort_order,title')->fetchAll();}
$adminLogo='<span class="brand-logo-window"><img class="brand-logo" src="/images/hhc-approved-logo.svg" alt="HAPPY HOME CARE — Elevated Care. Right at Home."></span>';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($titles[$page])?> · Admin · HAPPY HOME CARE</title><link rel="stylesheet" href="/assets/styles.css"><link rel="stylesheet" href="/assets/admin.css"></head><body class="admin-body"><div class="admin-shell"><aside class="admin-sidebar"><a class="brand" href="/"><?=$adminLogo?></a><nav><?php foreach(['dashboard'=>'Overview','inquiries'=>'Care requests','applications'=>'Applications','services'=>'Services','locations'=>'Locations','resources'=>'Resources','faqs'=>'FAQs','testimonials'=>'Testimonials','caregivers'=>'Caregivers','settings'=>'Website details'] as $key=>$label): ?><a class="<?=$page===$key?'active':''?>" href="/admin/?page=<?=$key?>"><?=e($label)?></a><?php endforeach; ?></nav><form method="post" action="/admin/logout.php"><?=csrf_field()?><button type="submit">Sign out · <?=e($_SESSION['admin_name']??'Admin')?></button></form></aside><main class="admin-main"><header class="admin-top"><h1><?=e($titles[$page])?></h1><span><?=e($_SESSION['admin_email']??'')?></span></header><?php if($flash): ?><div class="admin-alert" role="status"><?=e($flash['message'])?></div><?php endif; ?><?php if($error): ?><div class="admin-alert error"><?=e($error)?></div><?php endif; ?>
<?php if($page==='dashboard'): ?><div class="admin-stats"><?php foreach($counts as $label=>$count): ?><div class="admin-stat"><strong><?=$count?></strong><span><?=e($label)?></span></div><?php endforeach; ?></div><div class="admin-panel"><h2>Welcome, <?=e($_SESSION['admin_name']??'')?></h2><p>Update website content, review incoming care requests, and track caregiver applications from the menu.</p><div class="row-actions"><a class="edit-link" href="/">Open public website ↗</a><a class="edit-link" href="/admin/?page=inquiries">Review care requests →</a></div></div><section class="admin-panel service-admin-panel"><h2>Currently offered services</h2><?php if($dashboardServices): ?><ul class="service-admin-list"><?php foreach($dashboardServices as $offered): ?><li><?=e($offered['title'])?></li><?php endforeach; ?></ul><?php else: ?><p>No active services are published. Add services in the Services section.</p><?php endif; ?><a class="edit-link" href="/admin/?page=services">Manage services →</a></section><?php endif; ?>
<?php if($page==='settings'): ?><section class="admin-panel"><h2>Contact and homepage details</h2><form method="post" class="admin-form"><?=csrf_field()?><input type="hidden" name="action" value="save_settings"><?php foreach(['phone'=>'Display phone','phone_link'=>'Phone number for click-to-call (digits only)','email'=>'Contact email','hero_intro'=>'Homepage introduction'] as $key=>$label): ?><label><?=e($label)?><?php if($key==='hero_intro'): ?><textarea name="<?=$key?>" rows="3"><?=e(setting($key))?></textarea><?php else: ?><input name="<?=$key?>" value="<?=e(setting($key))?>" required><?php endif; ?></label><?php endforeach; ?><button class="button" type="submit">Save website details</button></form></section><?php endif; ?>
<?php if($module): ?><div class="admin-grid"><section class="admin-panel"><h2><?=$editing?'Edit item':'Add item'?></h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save_content"><input type="hidden" name="id" value="<?=e($editing['id']??'')?>"><?php foreach($module['fields'] as $key=>[$label,$type]): ?><label><?=e($label)?><?php if($type==='textarea'): ?><textarea name="<?=e($key)?>" rows="4" required><?=e($editing[$key]??'')?></textarea><?php elseif($type==='checkbox'): ?><input type="checkbox" name="<?=e($key)?>" value="1" <?=(!isset($editing[$key])||(int)$editing[$key]===1)?'checked':''?>><?php else: ?><input type="<?=e($type)?>" name="<?=e($key)?>" value="<?=e($editing[$key]??'')?>" <?=($key==='photo_url')?'':'required'?>><?php endif; ?></label><?php endforeach; ?><div class="form-actions"><button class="button" type="submit"><?=$editing?'Save changes':'Add item'?></button><?php if($editing): ?><a class="edit-link" href="/admin/?page=<?=e($page)?>">Cancel</a><?php endif; ?></div></form></section><section class="admin-panel"><h2>Current items (<?=count($rows)?>)</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>Content</th><th>Visibility</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?=e($row['id'])?></td><td><?php $titleField=array_intersect(['title','question','customer_name','full_name','city'],array_keys($module['fields']));$displayKey=$titleField?reset($titleField):'id'; ?><strong><?=e($row[$displayKey]??'')?></strong><br><small><?=e($row['summary']??$row['answer']??$row['quote']??$row['role']??$row['state']??'')?></small></td><td><?=((int)($row['active']??$row['published']??1)===1)?'Shown':'Hidden'?></td><td class="actions"><div class="row-actions"><a class="edit-link" href="/admin/?page=<?=e($page)?>&edit=<?=$row['id']?>">Edit</a><form method="post" onsubmit="return confirm('Remove this item?')"><?=csrf_field()?><input type="hidden" name="action" value="delete_content"><input type="hidden" name="id" value="<?=$row['id']?>"><button class="danger-button" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div><?php endif; ?>
<?php if(in_array($page,['inquiries','applications'],true)): ?><section class="admin-panel"><h2><?=count($rows)?> most recent submissions</h2><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Received</th><th>Name & contact</th><th>Request</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?=e(date('M j, Y g:i a',strtotime($row['created_at'])))?></td><td><strong><?=e($row['first_name'].' '.$row['last_name'])?></strong><br><a href="mailto:<?=e($row['email'])?>"><?=e($row['email'])?></a><br><?php if($row['phone']??''): ?><a href="tel:<?=e(preg_replace('/\D/','',$row['phone']))?>"><?=e($row['phone'])?></a><?php endif; ?></td><td><?php if($page==='inquiries'): ?><?=e($row['care_type'])?> · <?=e($row['zip_code'])?><br><small><?=e($row['details'])?></small><?php else: ?><?=e($row['role'])?><?php endif; ?></td><td><form method="post" class="row-actions"><?=csrf_field()?><input type="hidden" name="action" value="update_status"><input type="hidden" name="id" value="<?=$row['id']?>"><select class="status-select" name="status" onchange="this.form.submit()"><?php foreach(($page==='inquiries'?['new','contacted','closed']:['new','reviewing','contacted','closed']) as $status): ?><option value="<?=$status?>" <?=$row['status']===$status?'selected':''?>><?=ucfirst($status)?></option><?php endforeach; ?></select></form></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
</main></div></body></html>
